<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { useUserCenterStore } from '../../stores/userCenter'; import type { Address } from '../../api/userCenter'
const store = useUserCenterStore(); const editing = ref<Address | null>(null); const form = ref({ name: '', phone: '', province: '', city: '', district: '', detail: '' }); const reset = () => { editing.value = null; form.value = { name: '', phone: '', province: '', city: '', district: '', detail: '' } }; function edit(a: Address) { editing.value = a; form.value = { name: a.name, phone: a.phone, province: a.province, city: a.city, district: a.district, detail: a.detail } } async function save() { if (!/^\d{11}$/.test(form.value.phone) || !form.value.name || !form.value.detail) { alert('Please enter recipient, 11-digit phone and detail.'); return } await store.saveAddress(form.value, editing.value?.id); reset() } function confirmDelete(id: number) { if (confirm('Delete this address?')) store.removeAddress(id) } onMounted(() => store.loadAddresses())
</script>
<template><div class="user-heading"><div><p class="eyebrow">ADDRESS BOOK</p><h1>Addresses</h1></div><button @click="reset">Add address</button></div><div class="address-list"><article v-for="address in store.addresses" :key="address.id" class="address-card"><div><strong>{{ address.name }}</strong><span>{{ address.phone.slice(0, 3) }}****{{ address.phone.slice(-4) }}</span><em v-if="address.isDefault">Default</em><p>{{ address.province }}{{ address.city }}{{ address.district }}{{ address.detail }}</p></div><div class="address-actions"><button v-if="!address.isDefault" @click="store.makeDefault(address.id)">Set default</button><button @click="edit(address)">Edit</button><button @click="confirmDelete(address.id)">Delete</button></div></article></div><div v-if="editing || form.name || form.detail" class="user-panel address-form"><h2>{{ editing ? 'Edit address' : 'New address' }}</h2><div class="form-grid"><input v-model="form.name" placeholder="Recipient"/><input v-model="form.phone" placeholder="Phone" maxlength="11"/><input v-model="form.province" placeholder="Province"/><input v-model="form.city" placeholder="City"/><input v-model="form.district" placeholder="District"/><input v-model="form.detail" placeholder="Street and number"/></div><button @click="save">Save</button><button class="secondary-button" @click="reset">Cancel</button></div></template>
